import { argsFromPositional } from '../../binaries/util.js';
import { hasDependency } from '../../util/plugin.js';
import { resolveFromAST } from './resolveFromAST.js';
const title = 'SST';
const enablers = ['sst'];
const isEnabled = ({ dependencies }) => hasDependency(dependencies, enablers);
const config = ['sst.config.ts'];
const wrappers = new Set(['bind', 'dev', 'env', 'shell']);
const args = {
    boolean: ['print-logs', 'script'],
    config: ['config'],
    fromArgs: (parsed, args) => {
        if (!wrappers.has(parsed._[0]))
            return [];
        const command = argsFromPositional(parsed, args, 1);
        return parsed._[0] === 'bind' || parsed._[0] === 'env' ? command.join(' ') : command;
    },
};
const plugin = {
    title,
    enablers,
    isEnabled,
    config,
    resolveFromAST,
    args,
};
export default plugin;
